Incld_EE as( 
SELECT 
       p.EXTRL_NTITY_SEQ_ID

FROM 
     Incld_Occrs p 
GROUP BY  
      p.EXTRL_NTITY_SEQ_ID, p.EN_EFCTV_RISK_NB
HAVING 
            (
            (p.EN_EFCTV_RISK_NB >= @Effctv_Risk_Cutoff_Lvl 
                      and count(distinct p.OCC_NB) >= DECODE(max(p.EE_Repeating_Fl),'R', @HR_Min_Occurrence_Ct, @HR_NR_Min_Occurrence_Ct)
            )
              or
            (p.EN_EFCTV_RISK_NB < @Effctv_Risk_Cutoff_Lvl
                       and count(distinct p.OCC_NB) >= DECODE(max(p.EE_Repeating_Fl),'R', @RR_Min_Occurrence_Ct, @RR_NR_Min_Occurrence_Ct)
            )
            )      
        AND max(p.Data_Dump_Dt_Max) > (select Freq_Dt from clndr_vw)  
        AND max(p.Data_Dump_Dt_Max) <= (select Max_Dt from clndr_vw)  
)    

--Transactions
SELECT 

       a.EXTRL_NTITY_SEQ_ID,
       b.FO_TRXN_SEQ_ID
FROM TABLE(@MINER@.DEPWD_EN_DEP_WIRE_PIPELINE( 
        @All_Jurisdictions_Fl,
        @All_Trans_Src_Fl,
        @Curr_Type,
        @EN_Smry_Lookback_Period,
        @Effctv_Risk_Cutoff_Lvl,
        @Frequency_Period,
