(select add_days(cal.CLNDR_DT, -@Frequency_Period) from KDD_CAL cal where cal.CLNDR_NM = 'SYSCAL' and cal.CLNDR_DAY_AGE = 0) as  Freq_Dt
FROM dual
),


Incld_EE as( 
SELECT 
       p.EXTRL_NTITY_SEQ_ID

