HAVING 
            (
            (p.EN_EFCTV_RISK_NB >= @Effctv_Risk_Cutoff_Lvl 
                      and count(distinct p.OCC_NB) >= DECODE(max(p.EE_Repeating_Fl),'R', @HR_Min_Occurrence_Ct, @HR_NR_Min_Occurrence_Ct)
            )
              or
            (p.EN_EFCTV_RISK_NB < @Effctv_Risk_Cutoff_Lvl
                       and count(distinct p.OCC_NB) >= DECODE(max(p.EE_Repeating_Fl),'R', @RR_Min_Occurrence_Ct, @RR_NR_Min_Occurrence_Ct)
            )
            )   
        AND max(p.Data_Dump_Dt_Max) > (select Freq_Dt from clndr_vw)  
        AND max(p.Data_Dump_Dt_Max) <= (select Max_Dt from clndr_vw)

with Incld_Occrs as
 (SELECT 
         a.EXTRL_NTITY_SEQ_ID,
         a.EN_EFCTV_RISK_NB,
         a.OCC_NB, 
         max(a.TOT_TRXN_CT) as Tot_Trxn_Ct_Max,
         max(a.TOT_TRXN_AMT) as Tot_Trxn_Amt_Max,
         max(a.DATA_DUMP_DT) as Data_Dump_Dt_Max,
         max(a.Hr_Trxn_Am) as Hr_Trxn_Am_Max,
         max(a.Pass_Thru_Trxn_Am) as Pass_Thru_Trxn_Am_Max,
         max(a.Lrf_Trxn_Am) as Lrf_Trxn_Am_Max,
         max(TOT_TRXN_BASE_AMT) as Tot_Trxn_Base_Amt_Max,
         max(TOT_TRXN_FUNC_AMT) as Tot_Trxn_Func_Amt_Max,
         max(FUNC_CRNCY_CD) as Func_Crncy_Cd,
         max(EE_REP_NONREP_FL) as EE_Repeating_Fl
        FROM TABLE(@MINER@.DEPWD_EN_CASH_PIPELINE( 
        @All_Jurisdictions_Fl,
        @All_Trans_Src_Fl,
        @Curr_Type,
        @EN_Smry_Lookback_Period,
        @Effctv_Risk_Cutoff_Lvl,
        @Frequency_Period,
        @HR_Min_Indiv_Trans_Amt,
        @HR_Min_Occurrence_Ct,
        @HR_Min_Trans_Amt,
        @HR_Min_Trans_Ct,
        @HR_NR_Min_Indiv_Trans_Amt,
        @HR_NR_Min_Occurrence_Ct,
        @HR_NR_Min_Trans_Amt,
        @HR_NR_Min_Trans_Ct,
        @HR_NR_Same_Amt_Range,
        @HR_Same_Amt_Range,
        @Incl_Cash_Trns_Fl,
        @MINER@.Lst(@Incl_Jurisdictions_Lst),
        @Incl_Mi_Trns_Fl,
        @Incl_Rltd_Parties,
        @MINER@.Lst(@Incl_Trans_Src_Lst),
        @Incl_Wire_Trns_Fl,
        @MINER@.Lst(@Incl_Cash_Trxn_Prdct_Type_Lst),
        @Include_B2B_Trnfr_Fl,
        @Lrf_Digits,
        @Look_Back_Period,
        @Min_EN_Trns_Amt,
        @Min_EN_Trns_Ct,
        @RR_Min_Indiv_Trans_Amt,
        @RR_Min_Occurrence_Ct,
        @RR_Min_Trans_Amt,
        @RR_Min_Trans_Ct,
        @RR_NR_Min_Indiv_Trans_Amt,
        @RR_NR_Min_Occurrence_Ct,
        @RR_NR_Min_Trans_Amt,
        @RR_NR_Min_Trans_Ct,
        @RR_NR_Same_Amt_Range,
        @RR_Same_Amt_Range,
         'D' -- call function for Debit side
               )) a
   GROUP BY a.EXTRL_NTITY_SEQ_ID, a.EN_EFCTV_RISK_NB, a.OCC_NB
   HAVING 
   ((a.EN_EFCTV_RISK_NB >= @Effctv_Risk_Cutoff_Lvl 
                          and max(a.TOT_TRXN_CT) >= DECODE(max(EE_REP_NONREP_FL), 'R', @HR_Min_Trans_Ct, @HR_NR_Min_Trans_Ct) 
                          and max(a.TOT_TRXN_AMT) >= DECODE(max(EE_REP_NONREP_FL), 'R', @HR_Min_Trans_Amt, @HR_NR_Min_Trans_Amt)
     )
   or
   (a.EN_EFCTV_RISK_NB < @Effctv_Risk_Cutoff_Lvl 
                          and max(a.TOT_TRXN_CT) >= DECODE(max(EE_REP_NONREP_FL), 'R', @RR_Min_Trans_Ct, @RR_NR_Min_Trans_Ct) 
                          and max(a.TOT_TRXN_AMT) >= DECODE(max(EE_REP_NONREP_FL), 'R', @RR_Min_Trans_Amt, @RR_NR_Min_Trans_Amt)
     )
   )       
),

clndr_vw as ( 
select
(select add_days(cal.CLNDR_DT, -@Look_Back_Period) from KDD_CAL cal where cal.CLNDR_NM = 'SYSCAL' and cal.CLNDR_DAY_AGE = 0) as Min_Dt,
(select cal.clndr_dt from KDD_CAL cal where cal.CLNDR_NM = 'SYSCAL' and cal.CLNDR_DAY_AGE = 0) as Max_Dt,
(select add_days(cal.CLNDR_DT, -@Frequency_Period) from KDD_CAL cal where cal.CLNDR_NM = 'SYSCAL' and cal.CLNDR_DAY_AGE = 0) as  Freq_Dt
FROM dual
)


SELECT 
       p.EXTRL_NTITY_SEQ_ID, 
       p.EN_EFCTV_RISK_NB,
       case when p.EN_EFCTV_RISK_NB >= @Effctv_Risk_Cutoff_Lvl
            then 'HR'
            else 'RR'
       end as Overall_Risk,     
       count(distinct p.OCC_NB) as Occ_Ct,
       sum(p.Tot_Trxn_Ct_Max) as Tot_Trxn_Ct,
       sum(p.Tot_Trxn_Amt_Max) as Tot_Trxn_Amt,
       max(p.Data_Dump_Dt_Max) as Data_Dump_Dt,
       sum(p.Hr_Trxn_Am_Max) as Hr_Trxn_Amt,
       (sum(p.Hr_Trxn_Am_Max) / sum(p.Tot_Trxn_Amt_Max)) * 100 as Hr_Prctg,
       sum(p.Pass_Thru_Trxn_Am_Max) as Pass_Thru_Trxn_Amt,
       (sum(p.Pass_Thru_Trxn_Am_Max) / sum(p.Tot_Trxn_Amt_Max)) * 100 as Pass_Thru_Prctg,
       sum(p.Lrf_Trxn_Am_Max) as Lrf_Trxn_Amt,
       (sum(p.Lrf_Trxn_Am_Max) / sum(p.Tot_Trxn_Amt_Max)) * 100 as Lrf_Prctg,
       (select Max_Dt from clndr_vw) as Curr_Dt,
       sum(Tot_Trxn_Base_Amt_Max) as Tot_Trxn_Base_Amt,
       sum(Tot_Trxn_Func_Amt_Max) as Tot_Trxn_Func_Amt,
       max(Func_Crncy_Cd) as Func_Crncy_Cd,
       max(EE_Repeating_Fl) as EE_Repeating_Fl  
FROM 
     Incld_Occrs p 
GROUP BY  
      p.EXTRL_NTITY_SEQ_ID, p.EN_EFCTV_RISK_NB
HAVING 
            (
            (p.EN_EFCTV_RISK_NB >= @Effctv_Risk_Cutoff_Lvl 
                      and count(distinct p.OCC_NB) >= DECODE(max(p.EE_Repeating_Fl),'R', @HR_Min_Occurrence_Ct, @HR_NR_Min_Occurrence_Ct)
            )
              or
            (p.EN_EFCTV_RISK_NB < @Effctv_Risk_Cutoff_Lvl
