         'C'  -- credit side
               )) a
   GROUP BY a.EXTRL_NTITY_SEQ_ID, a.EN_EFCTV_RISK_NB, a.OCC_NB
   HAVING 
   ((a.EN_EFCTV_RISK_NB >= @Effctv_Risk_Cutoff_Lvl 
                          and max(a.TOT_TRXN_CT) >= DECODE(max(EE_REP_NONREP_FL), 'R', @HR_Min_Trans_Ct, @HR_NR_Min_Trans_Ct) 
                          and max(a.TOT_TRXN_AMT) >= DECODE(max(EE_REP_NONREP_FL), 'R', @HR_Min_Trans_Amt, @HR_NR_Min_Trans_Amt)
     )
   or
   (a.EN_EFCTV_RISK_NB < @Effctv_Risk_Cutoff_Lvl 
                          and max(a.TOT_TRXN_CT) >= DECODE(max(EE_REP_NONREP_FL), 'R', @RR_Min_Trans_Ct, @RR_NR_Min_Trans_Ct) 
                          and max(a.TOT_TRXN_AMT) >= DECODE(max(EE_REP_NONREP_FL), 'R', @RR_Min_Trans_Amt, @RR_NR_Min_Trans_Amt)
     )
   )        
),

clndr_vw as ( 
select
(select add_days(cal.CLNDR_DT, -@Look_Back_Period) from KDD_CAL cal where cal.CLNDR_NM = 'SYSCAL' and cal.CLNDR_DAY_AGE = 0) as Min_Dt,
(select cal.clndr_dt from KDD_CAL cal where cal.CLNDR_NM = 'SYSCAL' and cal.CLNDR_DAY_AGE = 0) as Max_Dt,
(select add_days(cal.CLNDR_DT, -@Frequency_Period) from KDD_CAL cal where cal.CLNDR_NM = 'SYSCAL' and cal.CLNDR_DAY_AGE = 0) as  Freq_Dt
FROM dual
),


Incld_EE as( 
SELECT 
       p.EXTRL_NTITY_SEQ_ID

FROM 
     Incld_Occrs p 
GROUP BY  
      p.EXTRL_NTITY_SEQ_ID, p.EN_EFCTV_RISK_NB
HAVING 
            (
            (p.EN_EFCTV_RISK_NB >= @Effctv_Risk_Cutoff_Lvl 
                      and count(distinct p.OCC_NB) >= DECODE(max(p.EE_Repeating_Fl),'R', @HR_Min_Occurrence_Ct, @HR_NR_Min_Occurrence_Ct)
            )
              or
            (p.EN_EFCTV_RISK_NB < @Effctv_Risk_Cutoff_Lvl
                       and count(distinct p.OCC_NB) >= DECODE(max(p.EE_Repeating_Fl),'R', @RR_Min_Occurrence_Ct, @RR_NR_Min_Occurrence_Ct)
            )
            )      
        AND max(p.Data_Dump_Dt_Max) > (select Freq_Dt from clndr_vw)  
        AND max(p.Data_Dump_Dt_Max) <= (select Max_Dt from clndr_vw)  
)    

