        @RR_NR_Min_Trans_Ct,
        @RR_NR_Same_Amt_Range,
        @RR_Same_Amt_Range,
         'C'  -- credit side
               )) b,
       Incld_EE a,
       Incld_Occrs o

  WHERE  
           b.EXTRL_NTITY_SEQ_ID = a.EXTRL_NTITY_SEQ_ID      
       and a.EXTRL_NTITY_SEQ_ID = o.EXTRL_NTITY_SEQ_ID
       and b.OCC_NB = o.OCC_NB

