        @Look_Back_Period,
        @Min_EN_Trns_Amt,
        @Min_EN_Trns_Ct,
        @RR_Min_Indiv_Trans_Amt,
        @RR_Min_Occurrence_Ct,
        @RR_Min_Trans_Amt,
        @RR_Min_Trans_Ct,
        @RR_NR_Min_Indiv_Trans_Amt,
        @RR_NR_Min_Occurrence_Ct,
        @RR_NR_Min_Trans_Amt,
        @RR_NR_Min_Trans_Ct,
        @RR_NR_Same_Amt_Range,
        @RR_Same_Amt_Range,
         'D'    -- Debit side
               )) a
   GROUP BY a.EXTRL_NTITY_SEQ_ID, a.EN_EFCTV_RISK_NB, a.OCC_NB
   HAVING 
